    mx, mn = max(r, g, b), min(r, g, b)
    df = mx - mn
    if mx == mn:
        h = 0
    elif mx == r:
        h = (60 * ((g - b) / df)) % 360
    elif mx == g:
        h = (60 * ((b - r) / df)) + 120
